def lvl(P):
    n1, n2, n3 = P['n']; f = lambda x: str(x)
    c = n1 * (n1 - 1) * (n1 - 2) // 6
    o1 = M4(1, 'There are %d points in space, no four in one plane. How many planes pass through three of them?' % n1, 'Cho %d điểm trong không gian, không có bốn điểm nào đồng phẳng. Có bao nhiêu mặt phẳng đi qua ba trong số các điểm đó?' % n1, f(c), [f(n1 * (n1 - 1) * (n1 - 2)), f(c + n1), f(c - 1), f(c + 1)], 'Choose 3 of %d points: %d.' % (n1, c), 'Chọn 3 trong %d điểm: %d.' % (n1, c))
    o2 = M4(2, 'A pyramid has a base with %d sides. It has … edges.' % n2, 'Hình chóp có đáy là đa giác %d cạnh. Số cạnh của hình chóp là…' % n2, f(2 * n2), [f(n2 + 1), f(3 * n2), f(2 * n2 + 1)], '%d base edges and %d lateral edges.' % (n2, n2), '%d cạnh đáy và %d cạnh bên.' % (n2, n2))
    o3 = M4(3, 'A prism has a base with %d sides. It has … faces.' % n3, 'Hình lăng trụ có đáy là đa giác %d cạnh. Số mặt của lăng trụ là…' % n3, f(n3 + 2), [f(n3), f(n3 + 1), f(2 * n3)], '%d lateral faces and 2 bases.' % n3, '%d mặt bên và 2 đáy.' % n3)
    st4 = [('Three points always lie in exactly one plane.', 'Ba điểm bất kì luôn nằm trong đúng một mặt phẳng.', False), ('Three non-collinear points lie in exactly one plane.', 'Ba điểm không thẳng hàng nằm trong đúng một mặt phẳng.', True), ('A line and a point not on it lie in exactly one plane.', 'Một đường thẳng và một điểm không thuộc nó nằm trong đúng một mặt phẳng.', True)][P['s4']]
    t4 = tf(4, st4[0], st4[1], st4[2], 'Collinear points lie in infinitely many planes; non-collinear ones in exactly one.', 'Ba điểm thẳng hàng nằm trong vô số mặt phẳng; ba điểm không thẳng hàng nằm trong đúng một mặt phẳng.')
    st5 = [('Two different planes with a common point have exactly one common point.', 'Hai mặt phẳng phân biệt có một điểm chung thì chỉ có đúng một điểm chung.', False), ('Two different planes with a common point share a whole line.', 'Hai mặt phẳng phân biệt có một điểm chung thì có chung cả một đường thẳng.', True), ('If a line has two points in a plane, it lies in the plane.', 'Nếu đường thẳng có hai điểm thuộc một mặt phẳng thì nó nằm trong mặt phẳng đó.', True)][P['s5']]
    t5 = tf(5, st5[0], st5[1], st5[2], 'This is one of the basic axioms.', 'Đây là một trong các tiên đề cơ bản.')
    m = P['m']; s6 = sh(6, 'There are %d points in space, no four in one plane. How many planes pass through three of them?' % m, 'Có %d điểm trong không gian, không có bốn điểm nào đồng phẳng. Có bao nhiêu mặt phẳng đi qua ba trong số các điểm đó?' % m, m * (m - 1) * (m - 2) // 6, '\\(\\binom{%d}{3}\\).' % m, '\\(\\binom{%d}{3}\\).' % m)
    k = P['k']; s7 = sh(7, 'A pyramid has a base with %d sides. How many faces does it have?' % k, 'Hình chóp có đáy là đa giác %d cạnh. Hình chóp có bao nhiêu mặt?' % k, k + 1, '%d lateral faces and the base.' % k, '%d mặt bên và mặt đáy.' % k)
    return [[o1, o2, o3], [t4, t5], [s6, s7]]
PP = [dict(n=(4, 5, 3), s4=0, s5=1, m=9, k=4), dict(n=(5, 6, 4), s4=1, s5=0, m=7, k=7), dict(n=(6, 8, 5), s4=2, s5=2, m=8, k=9)]
